module TopModule (
    input  logic       in,
    input  logic [1:0] state,
    output logic [1:0] next_state,
    output logic       out
);

  always_comb begin
    // Default values
    next_state = state;
    out = 1'b0;

    case (state)
      2'b00: begin // State A
        out = 1'b0;
        if (in)
          next_state = 2'b01; // B
        else
          next_state = 2'b00; // A
      end

      2'b01: begin // State B
        out = 1'b0;
        if (in)
          next_state = 2'b01; // B
        else
          next_state = 2'b10; // C
      end

      2'b10: begin // State C
        out = 1'b0;
        if (in)
          next_state = 2'b11; // D
        else
          next_state = 2'b00; // A
      end

      2'b11: begin // State D
        out = 1'b1;
        if (in)
          next_state = 2'b01; // B
        else
          next_state = 2'b10; // C
      end

      default: begin
        next_state = 2'b00;
        out        = 1'b0;
      end
    endcase
  end

endmodule

